import { Context, Effect, Layer, Redacted, Schema } from "effect";

import { SendblueConfigService } from "./config.js";
import { SendblueRoutingError } from "./errors.js";
import { SendblueConversationKey } from "./schemas.js";
import type { E164PhoneNumber, SendblueConversationKey as SendblueConversationKeyType } from "./schemas.js";

const textEncoder = new TextEncoder();

export const keyedSendblueDigest = (
  key: Redacted.Redacted<string>,
  values: readonly string[]
) =>
  Effect.tryPromise({
    try: async () => {
      const cryptoKey = await globalThis.crypto.subtle.importKey(
        "raw",
        textEncoder.encode(Redacted.value(key)),
        { hash: "SHA-256", name: "HMAC" },
        false,
        ["sign"]
      );
      const signature = await globalThis.crypto.subtle.sign(
        "HMAC",
        cryptoKey,
        textEncoder.encode(values.join("\u0000"))
      );
      return Array.from(new Uint8Array(signature), (byte) =>
        byte.toString(16).padStart(2, "0")
      ).join("");
    },
    catch: () =>
      new SendblueRoutingError({
        message: "Unable to derive the Sendblue conversation key.",
      }),
  });

export interface SendblueSessionRouterShape {
  readonly route: (
    senderNumber: E164PhoneNumber,
    sendblueNumber: E164PhoneNumber
  ) => Effect.Effect<SendblueConversationKeyType, SendblueRoutingError>;
}

export class SendblueSessionRouter extends Context.Service<
  SendblueSessionRouter,
  SendblueSessionRouterShape
>()("@bundjil/agent/SendblueSessionRouter") {}

export const makeSendblueSessionRouter = (
  routingKey: Redacted.Redacted<string>
) =>
  SendblueSessionRouter.of({
    route: Effect.fn("SendblueSessionRouter.route")(function* (
      senderNumber,
      sendblueNumber
    ) {
      const digest = yield* keyedSendblueDigest(routingKey, [
        "conversation",
        senderNumber,
        sendblueNumber,
      ]);
      return yield* Schema.decodeUnknownEffect(SendblueConversationKey)(
        `sendblue:conversation:${digest}`
      );
    }).pipe(
      Effect.mapError(
        () =>
          new SendblueRoutingError({
            message: "Unable to derive the Sendblue conversation key.",
          })
      )
    ),
  });

export const SendblueSessionRouterLive = Layer.effect(
  SendblueSessionRouter,
  Effect.gen(function* makeSendblueSessionRouterLive() {
    const config = yield* SendblueConfigService;
    return makeSendblueSessionRouter(config.routingKey);
  })
);

import { Context, Effect, Layer, Redacted } from "effect";

import { SendblueConfigService } from "./config.js";
import { SendblueWebhookAuthenticationError } from "./errors.js";

const textEncoder = new TextEncoder();

const hasConstantTimeMatch = (expected: Uint8Array, received: Uint8Array) => {
  let difference = expected.length ^ received.length;
  for (let index = 0; index < expected.length; index += 1) {
    difference |= expected[index]! ^ (received[index] ?? 0);
  }
  return difference === 0;
};

export interface SendblueWebhookVerifierShape {
  readonly verify: (
    headers: Headers
  ) => Effect.Effect<void, SendblueWebhookAuthenticationError>;
}

export class SendblueWebhookVerifier extends Context.Service<
  SendblueWebhookVerifier,
  SendblueWebhookVerifierShape
>()("@bundjil/agent/SendblueWebhookVerifier") {}

export const makeSendblueWebhookVerifier = (
  webhookSecret: Redacted.Redacted<string>
) =>
  SendblueWebhookVerifier.of({
    verify: Effect.fn("SendblueWebhookVerifier.verify")(function* (headers) {
      const suppliedSecret = headers.get("sb-signing-secret");
      if (suppliedSecret === null) {
        return yield* new SendblueWebhookAuthenticationError({
          message: "The Sendblue webhook signing secret is missing.",
        });
      }

      const expected = textEncoder.encode(Redacted.value(webhookSecret));
      const received = textEncoder.encode(suppliedSecret);
      if (!hasConstantTimeMatch(expected, received)) {
        return yield* new SendblueWebhookAuthenticationError({
          message: "The Sendblue webhook signing secret is invalid.",
        });
      }
    }),
  });

export const SendblueWebhookVerifierLive = Layer.effect(
  SendblueWebhookVerifier,
  Effect.gen(function* makeSendblueWebhookVerifierLive() {
    const config = yield* SendblueConfigService;
    return makeSendblueWebhookVerifier(config.webhookSecret);
  })
);

