  Effect.gen(function* testUpstashClaimShape() {
    const commands: (readonly [string, string, { ex: number; nx: true }])[] =
      [];
    const client: UpstashReplayClient = {
      eval: async () => 1,
      set: async (key, value, options) => {
        commands.push([key, value, options]);
